class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);enableEdgeToEdge();setContent{MpScanTheme{HomeRoot()}}}}
private enum class Destination(val label:String,val icon:String){Home("Início","⌂"),Search("Busca","⌕"),Library("Biblioteca","▣"),Profile("Perfil","♙")}

@Composable private fun HomeRoot(){
 var selected by remember{mutableStateOf(Destination.Home)};var selectedWork by remember{mutableStateOf<Work?>(null)};var directReader by remember{mutableStateOf<Pair<Work,Chapter>?>(null)};var settingsOpen by remember{mutableStateOf(false)};var works by remember{mutableStateOf<List<Work>>(emptyList())};var loading by remember{mutableStateOf(true)};var error by remember{mutableStateOf("")}
 LaunchedEffect(Unit){runCatching{CatalogRepository().works()}.onSuccess{works=it}.onFailure{error="Não foi possível carregar o catálogo."};loading=false}
 Scaffold(containerColor=MpBackground,bottomBar={if(selectedWork==null&&directReader==null&&!settingsOpen)NavigationBar(containerColor=MpSurface){Destination.entries.forEach{x->NavigationBarItem(selected=selected==x,onClick={selected=x},icon={Text(x.icon)},label={Text(x.label)})}}}){p->
  Box(Modifier.fillMaxSize().padding(p)){when{settingsOpen->SettingsScreen{settingsOpen=false};directReader!=null->Reader(directReader!!.first,directReader!!.second){directReader=null};selectedWork!=null->WorkDetails(selectedWork!!,{selectedWork=null});selected==Destination.Library->OfflineLibrary(works,{selectedWork=it}){w,c->directReader=w to c};selected==Destination.Profile->AccountProfileScreen{settingsOpen=true};loading->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()};error.isNotBlank()->Message(error);works.isEmpty()->Message("As obras publicadas aparecerão aqui.");selected==Destination.Home->Home(works,Modifier,{selectedWork=it}){w,c->directReader=w to c};selected==Destination.Search->Search(works){selectedWork=it}}}
 }
}
@Composable private fun OfflineLibrary(works:List<Work>,openWork:(Work)->Unit,open:(Work,Chapter)->Unit){
 val context=LocalContext.current
 val store=remember{OfflineStore(context.applicationContext)}
 val readingStore=remember{ReadingStore(context.applicationContext)}
 val favorites=remember{FavoritesStore(context.applicationContext)}
 var downloads by remember{mutableStateOf(store.downloads())}
 var tab by remember{mutableStateOf("favorites")}
 val history=readingStore.history()
 Column(Modifier.fillMaxSize().padding(horizontal=16.dp)){
  Spacer(Modifier.height(16.dp));Header()
  Text("Biblioteca",fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineLarge,modifier=Modifier.padding(top=28.dp))
  Row(Modifier.padding(vertical=16.dp).horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){
   FilterChip(tab=="favorites",{tab="favorites"},{Text("Favoritos")})
   FilterChip(tab=="collections",{tab="collections"},{Text("Coleções")})
   FilterChip(tab=="downloads",{tab="downloads"},{Text("Downloads")})
   FilterChip(tab=="continue",{tab="continue"},{Text("Continuar lendo")})
   FilterChip(tab=="history",{tab="history"},{Text("Histórico")})
  }
  if(tab=="favorites"){
   val list=works.filter{favorites.contains(it.id)}
   if(list.isEmpty())LibraryEmpty("Você ainda não favoritou nenhuma obra","Use o botão Favoritar na tela da obra.")
   else LazyVerticalGrid(GridCells.Adaptive(140.dp),horizontalArrangement=Arrangement.spacedBy(12.dp),verticalArrangement=Arrangement.spacedBy(18.dp)){gridItems(list,key={it.id}){Card(it,openWork)}}
  }else if(tab=="collections") CollectionsPanel(works,openWork)
  else if(tab=="downloads"){
   val groups=downloads.groupBy{it.workId}.values.toList()
   if(groups.isEmpty())LibraryEmpty("Nenhuma obra baixada","Abra uma obra e use Baixar todos os capítulos.")
   else LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(bottom=24.dp)){items(groups,key={it.first().workId}){chapters->val saved=chapters.first();val work=works.firstOrNull{it.id==saved.workId}?:saved.toWork();DownloadedWorkRow(work,chapters.size){openWork(work)}}}
  }else if(tab=="continue") ProgressList(history.filter{it.percent<100}.distinctBy{it.workId},open,"Nenhuma leitura em andamento.")
  else ProgressList(history,open,"Seu histórico ainda está vazio.")
 }
}
@Composable private fun CollectionsPanel(works:List<Work>,openWork:(Work)->Unit){val context=LocalContext.current;val store=remember{CollectionsStore(context.applicationContext)};var names by remember{mutableStateOf(store.names())};var selected by remember{mutableStateOf<String?>(null)};var dialog by remember{mutableStateOf(false)};var rename by remember{mutableStateOf(false)};var input by remember{mutableStateOf("")};var members by remember(selected){mutableStateOf(selected?.let(store::works)?:emptySet())};if(dialog)AlertDialog(onDismissRequest={dialog=false},title={Text(if(rename)"Renomear coleção" else "Nova coleção")},text={OutlinedTextField(input,{input=it},singleLine=true,label={Text("Nome")})},confirmButton={TextButton({val current=selected;if(rename&&current!=null){if(store.rename(current,input)){selected=input.trim();names=store.names()}}else if(store.create(input)){names=store.names()};dialog=false}){Text("Salvar")}},dismissButton={TextButton({dialog=false}){Text("Cancelar")}});if(selected==null){Column{Button({input="";rename=false;dialog=true},shape=RoundedCornerShape(14.dp)){Text("＋ Criar coleção")};Spacer(Modifier.height(12.dp));if(names.isEmpty())LibraryEmpty("Nenhuma coleção criada","Crie coleções para organizar suas obras.")else LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(names,key={it}){name->Surface(Modifier.fillMaxWidth().clickable{selected=name;members=store.works(name)},color=MpSurface,shape=RoundedCornerShape(16.dp),border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text("▣",color=MpAccent);Column(Modifier.weight(1f).padding(horizontal=12.dp)){Text(name,fontWeight=FontWeight.Bold);Text("${store.works(name).size} obras",color=MpMuted,style=MaterialTheme.typography.bodySmall)};TextButton({store.delete(name);names=store.names()}){Text("Excluir")}}}}}}}else Column{Row(verticalAlignment=Alignment.CenterVertically){TextButton({selected=null}){Text("← Voltar")};Text(selected!!,fontWeight=FontWeight.Black,modifier=Modifier.weight(1f));TextButton({input=selected!!;rename=true;dialog=true}){Text("Renomear")}};Text("Toque para adicionar ou remover",color=MpMuted,modifier=Modifier.padding(bottom=10.dp));LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(works,key={it.id}){work->Surface(Modifier.fillMaxWidth().clickable{store.toggle(selected!!,work.id);members=store.works(selected!!)},color=MpSurface,shape=RoundedCornerShape(14.dp)){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(work.cover,work.title,Modifier.size(52.dp).clip(RoundedCornerShape(10.dp)),contentScale=ContentScale.Crop);Text(work.title,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f).padding(horizontal=10.dp),maxLines=1);Checkbox(work.id in members,{store.toggle(selected!!,work.id);members=store.works(selected!!)})}}}}}}
