@Composable private fun Search(works:List<Work>,open:(Work)->Unit){
 var query by remember{mutableStateOf("")};var status by remember{mutableStateOf("")};var genre by remember{mutableStateOf("")}
 val genres=remember(works){works.flatMap{it.genres}.distinct().sorted()}
 val filtered=remember(works,query,status,genre){works.filter{w->(query.isBlank()||(w.title+" "+w.author+" "+w.genres.joinToString()).contains(query,true))&&(status.isBlank()||localizedStatus(w.status).equals(status,true))&&(genre.isBlank()||w.genres.any{it.equals(genre,true)})}}
 Column(Modifier.fillMaxSize().padding(horizontal=16.dp,vertical=14.dp)){Header();Spacer(Modifier.height(18.dp));OutlinedTextField(query,{query=it},Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(16.dp),leadingIcon={Text("⌕")},label={Text("Nome, gênero ou autor")});LazyRow(Modifier.padding(vertical=12.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){item{FilterChip(status.isBlank(),{status=""},{Text("Todos")})};items(listOf("Em andamento","Completa","Em pausa","Futura","Cancelada")){s->FilterChip(status==s,{status=if(status==s)"" else s},{Text(s)})}};if(genres.isNotEmpty())LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(genres){g->FilterChip(genre==g,{genre=if(genre==g)"" else g},{Text(g)})}};Text("${filtered.size} obras",color=MpMuted,modifier=Modifier.padding(vertical=10.dp));LazyVerticalGrid(GridCells.Adaptive(140.dp),horizontalArrangement=Arrangement.spacedBy(12.dp),verticalArrangement=Arrangement.spacedBy(18.dp)){gridItems(filtered,key={it.id}){Card(it,open)}}}
}
@Composable private fun WorkDetails(work:Work,back:()->Unit){
 val context=LocalContext.current;val favorites=remember{FavoritesStore(context.applicationContext)};val offlineStore=remember{OfflineStore(context.applicationContext)};val repository=remember{CatalogRepository()};val scope=rememberCoroutineScope()
 var favorite by remember(work.id){mutableStateOf(favorites.contains(work.id))};var chapters by remember(work.id){mutableStateOf<List<Chapter>>(emptyList())};var loading by remember(work.id){mutableStateOf(true)};var reading by remember(work.id){mutableStateOf<Chapter?>(null)}
 var downloadingAll by remember(work.id){mutableStateOf(false)};var bulkProgress by remember(work.id){mutableIntStateOf(0)};var bulkMessage by remember(work.id){mutableStateOf("")};var bulkError by remember(work.id){mutableStateOf("")}
 if(reading!=null){Reader(work,reading!!){reading=null};return}
 LaunchedEffect(work.id){val saved=offlineStore.downloads().filter{it.workId==work.id}.map{it.toChapter()};runCatching{repository.chapters(work.id)}.onSuccess{remote->chapters=(remote+saved).distinctBy{it.id}.sortedByDescending{it.number?:-1.0}}.onFailure{chapters=saved};loading=false}
 LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=30.dp)){
  item{Box(Modifier.fillMaxWidth().height(320.dp)){AsyncImage(work.banner.ifBlank{work.cover},work.title,Modifier.fillMaxSize(),contentScale=ContentScale.Crop);Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color(0x55000000),MpBackground))));FilledTonalButton(back,Modifier.padding(16.dp)){Text("←")}}}
  item{Row(Modifier.padding(horizontal=16.dp)){AsyncImage(work.cover,work.title,Modifier.width(116.dp).aspectRatio(3f/4f).clip(RoundedCornerShape(18.dp)),contentScale=ContentScale.Crop);Column(Modifier.padding(start=16.dp)){Text(work.type.uppercase(),color=MpAccent2,style=MaterialTheme.typography.labelSmall);Text(work.title,fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall);Text(localizedStatus(work.status),color=MpMuted,modifier=Modifier.padding(top=8.dp));Text(work.author,color=MpMuted);Button({favorite=favorites.toggle(work.id)},Modifier.padding(top=12.dp),shape=RoundedCornerShape(14.dp)){Text(if(favorite)"♥ Favoritado" else "♡ Favoritar")}}}}
  item{Column(Modifier.padding(horizontal=16.dp,vertical=12.dp)){Button(onClick={scope.launch{if(chapters.isEmpty())return@launch;downloadingAll=true;bulkError="";bulkMessage="Preparando downloads…";val pending=chapters.filter{offlineStore.localPages(work.id,it.id).isEmpty()};if(pending.isEmpty()){bulkProgress=100;bulkMessage="Todos os capítulos já estão baixados."}else{var completed=0;for(chapter in pending){bulkMessage="Baixando ${chapter.label}";val result=runCatching{val pages=repository.pages(work.id,chapter.id);offlineStore.download(work,chapter,pages){pageProgress->bulkProgress=((completed*100)+pageProgress)/pending.size}};if(result.isFailure){bulkError="Alguns capítulos não puderam ser baixados.";break};completed++;bulkProgress=(completed*100)/pending.size};if(bulkError.isBlank())bulkMessage="Download de todos os capítulos concluído."};downloadingAll=false}},enabled=!loading&&!downloadingAll&&chapters.isNotEmpty(),modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(15.dp)){Text(if(downloadingAll)"Baixando… $bulkProgress%" else "⇣ Baixar todos os capítulos",fontWeight=FontWeight.Black)};if(downloadingAll)LinearProgressIndicator(progress={bulkProgress/100f},modifier=Modifier.fillMaxWidth().padding(top=8.dp));if(bulkMessage.isNotBlank())Text(bulkMessage,color=if(bulkError.isBlank())MpAccent2 else MaterialTheme.colorScheme.error,style=MaterialTheme.typography.bodySmall,modifier=Modifier.padding(top=7.dp));if(bulkError.isNotBlank())Text(bulkError,color=MaterialTheme.colorScheme.error,style=MaterialTheme.typography.bodySmall,modifier=Modifier.padding(top=3.dp))}}
